package com.mycompany.rentalmanagement.servlet;import com.mycompany.rentalmanagement.dao.RentalDAO;import com.mycompany.rentalmanagement.util.ValidationUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/rentals") public class RentalServlet extends HttpServlet{RentalDAO dao=new RentalDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("rentals",dao.list());r.setAttribute("customers",dao.customers());r.setAttribute("vehicles",dao.vehicles());r.getRequestDispatcher("/WEB-INF/views/rentals.jsp").forward(r,s);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/WEB-INF/views/error.jsp").forward(r,s);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{dao.book(Long.parseLong(r.getParameter("customer_id")),Long.parseLong(r.getParameter("vehicle_id")),ValidationUtil.date(r.getParameter("start_date"),"Start date"),ValidationUtil.date(r.getParameter("expected_return_date"),"Expected return date"),r.getParameter("notes"));s.sendRedirect(r.getContextPath()+"/rentals?success=1");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}}
